const pptxgen = require("pptxgenjs");
function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  slide.addText("Global CO₂ Emissions:\nWho Emits, How Much, and What's Changing", {
    x: 0.5, y: 1.5, w: 9, h: 1.5,
    fontSize: 44, fontFace: "Arial", color: theme.primary, bold: true, align: "left"
  });

  slide.addText("Scope: Fossil fuels & industry, 1750–2024", {
    x: 0.5, y: 3.2, w: 9, h: 0.5,
    fontSize: 24, fontFace: "Arial", color: theme.secondary, align: "left"
  });

  slide.addText("Data: Global Carbon Budget 2025 via Our World in Data\nAudience: Policy Analysts, Climate Negotiators, Sustainability Researchers", {
    x: 0.5, y: 4.5, w: 9, h: 0.8,
    fontSize: 14, fontFace: "Arial", color: theme.accent, align: "left", italic: true
  });
  return slide;
}
module.exports = { createSlide };
EOF

